label("$y$", r / 2, S);
label("$y$", s / 2, W);
label("$y$", p + (b - p) / 2, N);
label("$y$", q + (b - q) / 2, E);
label("$x$", r + (c - r) / 2, S);
label("$x$", s + (a - s) / 2, W);
label("$x$", c + (q - c) / 2, E);
label("$x$", a + (p - a) / 2, N);

